class TaskBinding {static Object book(int id,String[]authors,String publisher,int year){return new alternate.Book(id,"T"+id,authors,publisher,year,100,2.5,"hard");}static Object shortBook(){return new alternate.Book(9,"Short","Ann");}static Object[] array(Object...values){return java.util.Arrays.copyOf(values,values.length,alternate.Book[].class);}static alternate.Book[] books(Object[]a){return (alternate.Book[])a;}static Object[] author(Object[]a,String s){return alternate.Book.author(books(a),s);}static Object[] publisher(Object[]a,String s){return alternate.Book.publisher(books(a),s);}static Object[] after(Object[]a,int y){return alternate.Book.after(books(a),y);}static String state(Object a){alternate.Book b=(alternate.Book)a;return b.id()+"|"+b.title()+"|"+java.util.Arrays.toString(b.authors())+"|"+b.publisher()+"|"+b.year()+"|"+b.pages()+"|"+b.price()+"|"+b.binding();}static void edit(Object a){alternate.Book b=(alternate.Book)a;b.id(7);b.title("New");b.authors(new String[]{"Bob"});b.publisher("Q");b.year(2025);b.pages(40);b.price(3);b.binding("soft");}static String text(Object a){return a.toString();}static java.util.List<?> value(Object x){alternate.Book item=(alternate.Book)x;return java.util.List.of(item.id(),item.title(),java.util.List.of(item.authors()),item.publisher(),item.year(),item.pages(),item.price(),item.binding());}}
